sql_query:
SELECT COUNT(VAR_id) 
FROM varInfo_synthetic 
WHERE gene_name = 'NEK1' AND HighImpact = 'Y';

SELECT *
FROM varInfo_synthetic
WHERE ID = 'NEK1' AND HighImpact = 'True' AND CADDphred > 20;

SELECT *
FROM varInfo_synthetic
WHERE gene_name = 'NEK1' AND HighImpact = 'True' AND CADDphred > 20;

SELECT *
FROM varInfo_synthetic
WHERE ID = 'NEK1' AND HighImpact = 1 AND CADDphred > 20;

SELECT *
FROM varInfo_synthetic
WHERE ID = 'NEK1' AND HighImpact = 1 AND CADDphred > 20;

SELECT *
FROM varInfo_synthetic
WHERE gene_name = 'ABCA4' AND (HighImpact = '1' OR ModerateImpact = '1') AND CADDphred > 10 ORDER BY CADDphred DESC LIMIT 10;

SELECT ID, HighImpact, ModerateImpact, Synonymous, CADDphred 
FROM varInfo_synthetic 
WHERE gene_name = 'ABCA4' AND SIFT = 'deleterious' ORDER BY ABS(CAST(CADDphred AS REAL)) DESC LIMIT 10;

SELECT AVG(AF) AS avg_AF
FROM varInfo_synthetic
WHERE Synonymous = 'TRUE' OR ModerateImpact = 'TRUE' OR HighImpact = 'TRUE';

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE HighImpact = 'HIGH' AND gene_name = 'ALS_1';

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE ALS_1 = '1' AND HighImpact = '1';

SELECT * 
FROM varInfo_synthetic 
WHERE HighImpact = 'HIGH' OR ModerateImpact = 'MODERATE';

SELECT * 
FROM varInfo_synthetic 
WHERE Synonymous = 'TRUE' AND HighImpact = 'TRUE';

SELECT Control_4 
FROM varInfo_synthetic 
WHERE FILTER = 'PASS' AND gene_name = 'SOD1' AND ALS_2 > 0;
